package io.github.jesterportfolio.hearth.quest;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.inventory.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class QuestCompletionTest {
    static final class Store extends PersonalQuestTest.Store implements QuestCompletionStore {
        CompletableFuture<ChapterState> skip;int skips;
        @Override public CompletionStage<Saved> advanceQuest(ServerProgressAccess.Context c,String id,Saved before,Phase next,int index,long deadline){var f=new CompletableFuture<Saved>();pending.add(f);commit.add(()->{if(!rows.getOrDefault(key(c,id),new Saved(Phase.NOT_ACCEPTED,-1)).equals(before))f.completeExceptionally(new StorageFailure("quest","REVISION_CONFLICT"));else{var row=new Saved(next,before.revision()+1,index,deadline);rows.put(key(c,id),row);f.complete(row);}});return f;}
        public CompletionStage<ChapterState> skipChapter(ServerProgressAccess.Context c,QuestRules.Chapter ch){skips++;skip=new CompletableFuture<>();return skip;}
        public CompletionStage<Map<String,ChapterState>> readChapters(ServerProgressAccess.Context c){return CompletableFuture.completedFuture(Map.of());}
        public CompletionStage<String> rewardStatus(ServerProgressAccess.Context c,String q){throw new AssertionError();}
        public CompletionStage<InventoryStore.Stored> grantReward(ServerProgressAccess.Context c,String q,String h,long r,InventoryPayload p){throw new AssertionError();}
    }
    static final class Fixture {
        final Store store=new Store();final ArrayDeque<Runnable> queue=new ArrayDeque<>();final PersonalQuest quests=new PersonalQuest(store,Set.of("survey_marker"),queue::add,()->{});final QuestContent content=QuestBatchTest.content(false).quest("survey_marker");
        final ServerProgressAccess access=new ServerProgressAccess();final UUID run=UUID.randomUUID(),player=UUID.randomUUID();final ServerProgressAccess.Context ctx=access.forVerifiedServerLink(run,player);final Object token=new Object();long now=100;boolean valid=true;
        final QuestRules.Chapter chapter=new QuestRules.Chapter("chapter","공개 장","stage",List.of("survey_marker"),"hash");
        Fixture(QuestRules.Restart mode,long timeout){quests.rules(new QuestRules(Map.of("survey_marker",new QuestRules.Rule(mode,timeout>0?Set.of("OBJECTIVE","TIMEOUT"):Set.of("OBJECTIVE"),mode==QuestRules.Restart.CHECKPOINT?List.of(1):List.of(),timeout,null)),Map.of("chapter",chapter)));quests.clock(()->now);}
        void pump(){int i=500;while(!queue.isEmpty()){assertTrue(i-->0);queue.remove().run();}}
        PersonalQuest.Session open(){var ready=quests.open(ctx,"survey_marker",token,()->valid);pump();return ready.toCompletableFuture().join();}
        void commit(){store.commit.get(store.commit.size()-1).run();pump();}
    }
    @Test void allFailurePoliciesAndRetryPreserveRevisionAndTerminalCompletion(){for(var mode:QuestRules.Restart.values()){
        var f=new Fixture(mode,0);var q=f.open();f.quests.accept(q,f.content);f.commit();f.quests.reach(q,f.content,13,64,13);f.commit();f.quests.reach(q,f.content,19,64,13);f.commit();
        var failed=f.quests.fail(q,f.content,"OBJECTIVE");assertTrue(f.quests.fail(q,f.content,"OBJECTIVE").toCompletableFuture().isCompletedExceptionally());f.commit();int expected=switch(mode){case KEEP->2;case CHECKPOINT->1;case BEGINNING->0;};assertEquals(expected,q.saved().objectiveIndex());assertEquals(QuestStore.Phase.FAILED,failed.toCompletableFuture().join().phase());
        f.quests.retry(q,f.content);f.commit();assertEquals(4,q.saved().revision());for(int i=expected;i<3;i++){f.quests.reach(q,f.content,13+6*i,64,13);f.commit();}f.quests.advance(q,QuestStore.Phase.COMPLETED);f.commit();assertTrue(f.quests.retry(q,f.content).toCompletableFuture().isCompletedExceptionally());
    }}
    @Test void persistentDeadlineRejectsEarlyTimeoutThenExpiresOnceAndRetriesWithNewDeadline(){var f=new Fixture(QuestRules.Restart.KEEP,1000);var q=f.open();f.quests.accept(q,f.content);f.commit();assertEquals(1100,q.saved().deadlineMillis());assertTrue(f.quests.fail(q,f.content,"TIMEOUT").toCompletableFuture().isCompletedExceptionally());
        f.now=1100;assertTrue(f.quests.reach(q,f.content,13,64,13).toCompletableFuture().isCompletedExceptionally());var expired=f.quests.expire(QuestBatchTest.content(false));assertFalse(expired.toCompletableFuture().isDone());f.commit();assertEquals(QuestStore.Phase.FAILED,q.saved().phase());assertEquals(0,q.saved().deadlineMillis());f.quests.retry(q,f.content);f.commit();assertEquals(2100,q.saved().deadlineMillis());}
    @Test void failureSaveErrorKeepsOriginalAndHoldWhileStaleResponseCannotApply(){var f=new Fixture(QuestRules.Restart.BEGINNING,0);var q=f.open();f.quests.accept(q,f.content);f.commit();var before=q.saved();var failed=f.quests.fail(q,f.content,"OBJECTIVE");f.store.pending.getLast().completeExceptionally(new StorageFailure("quest","08006"));f.pump();assertTrue(failed.toCompletableFuture().isCompletedExceptionally());assertEquals(before,q.saved());assertTrue(q.held());assertTrue(f.quests.barrier(f.run).toCompletableFuture().isCompletedExceptionally());
        var g=new Fixture(QuestRules.Restart.KEEP,0);var old=g.open();g.quests.accept(old,g.content);g.commit();var work=g.quests.fail(old,g.content,"OBJECTIVE");g.valid=false;g.commit();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(QuestStore.Phase.ACTIVE,old.saved().phase());}
    @Test void chapterWaitsWritesBlocksNewRequestsAndIsInBarrier(){var f=new Fixture(QuestRules.Restart.KEEP,0);var q=f.open();var accepting=f.quests.accept(q,f.content);var skip=f.quests.skip(f.ctx,f.token,()->true,f.store,f.chapter);f.pump();assertEquals(0,f.store.skips);assertTrue(f.quests.list(f.ctx,f.token,()->true).toCompletableFuture().isCompletedExceptionally());f.commit();assertTrue(accepting.toCompletableFuture().isDone());assertEquals(1,f.store.skips);var barrier=f.quests.barrier(f.run);assertFalse(barrier.toCompletableFuture().isDone());
        f.store.rows.put(f.store.key(f.ctx),new QuestStore.Saved(QuestStore.Phase.SKIPPED,1));f.store.skip.complete(new QuestCompletionStore.ChapterState("chapter","hash",0));f.pump();assertTrue(skip.toCompletableFuture().isDone());assertTrue(barrier.toCompletableFuture().isDone());assertEquals(QuestStore.Phase.SKIPPED,f.open().saved().phase());}
    @Test void chapterUnknownCommitHoldsButNotPassedRejectionDoesNot(){for(String code:List.of("CHAPTER_NOT_PASSED","08006")){var f=new Fixture(QuestRules.Restart.KEEP,0);var work=f.quests.skip(f.ctx,f.token,()->f.valid,f.store,f.chapter);f.pump();f.store.skip.completeExceptionally(new StorageFailure("chapter",code));f.pump();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(code.equals("CHAPTER_NOT_PASSED"),f.quests.settled(f.run));}}
    @Test void skippedPrerequisiteUnlocksNextQuestButNeverBecomesActualCompletion(){var c=QuestCatalogTest.catalog();var q=new HashMap<>(QuestCatalogTest.quest("followup","survey_guide"));q.put("requires-completed","survey_marker");c=QuestCatalog.parse(List.of(QuestCatalogTest.npc("survey_guide",3)),List.of(QuestCatalogTest.quest("survey_marker","survey_guide"),q));
        var rows=Map.of("survey_marker",new QuestStore.Saved(QuestStore.Phase.SKIPPED,0),"followup",new QuestStore.Saved(QuestStore.Phase.NOT_ACCEPTED,-1));assertTrue(QuestListView.available(c.quest("followup"),rows));assertTrue(QuestListView.entries(c,rows).getFirst().status().contains("스킵"));assertTrue(QuestListView.filtered(c,rows,Set.of(),Set.of(),QuestListView.Filter.COMPLETED).isEmpty());}
    @Test void rulesValidateReferencesPoliciesAndKeepLegacyDefaults(){var c=QuestBatchTest.content(false);var rule=new HashMap<String,Object>(Map.of("id","survey_marker","restart","CHECKPOINT","failures",List.of("OBJECTIVE"),"checkpoints",List.of(1),"timeout-seconds",0));var root=new HashMap<String,Object>(Map.of("format",1,"quests",List.of(rule),"chapters",List.of()));assertEquals(QuestRules.Restart.CHECKPOINT,QuestRules.parse(root,c,null).rule("survey_marker").restart());
        for(Object invalid:List.of(List.of(2,1),List.of(3),List.of(-1),List.of(1,1))){rule.put("checkpoints",invalid);assertThrows(IllegalArgumentException.class,()->QuestRules.parse(root,c,null));}rule.put("checkpoints",List.of(1));rule.put("timeout-seconds",1);assertThrows(IllegalArgumentException.class,()->QuestRules.parse(root,c,null));assertEquals(QuestRules.DEFAULT,QuestRules.empty().rule("old"));}
    @Test void failureDuringObjectiveWriteWaitsAndRemainsInSaveBarrier(){var f=new Fixture(QuestRules.Restart.KEEP,0);var q=f.open();f.quests.accept(q,f.content);f.commit();var step=f.quests.reach(q,f.content,13,64,13);var trigger=f.quests.trigger(f.ctx,"OBJECTIVE",QuestBatchTest.content(false));f.pump();var barrier=f.quests.barrier(f.run);assertFalse(barrier.toCompletableFuture().isDone());f.commit();assertTrue(step.toCompletableFuture().isDone());assertFalse(trigger.toCompletableFuture().isDone());f.commit();assertEquals(QuestStore.Phase.FAILED,q.saved().phase());assertEquals(1,q.saved().objectiveIndex());assertTrue(barrier.toCompletableFuture().isDone());}
}
